/// GET /accounts/{account_id}/cni/interconnects
/// List existing interconnects
///
/// Returns `ClientRequestBuilder` for customization.
/// Use `list_interconnects_execute()` to send, or `list_interconnects` for simplest API.

pub fn list_interconnects_builder(
    client: &SimpleHttpClient,
    account_id: &String,
    site: &Option<Option<String>>,
    type_rs: &Option<Option<String>>,
    cursor: &Option<Option<String>>,
    limit: &Option<Option<String>>,
) -> Result<ClientRequestBuilder<SystemDnsResolver>, ApiError> {

    // Build URL
    let endpoint_url = format!(
        "https://api.cloudflare.com/client/v4/accounts/{}/cni/interconnects",
        account_id,
    );

    // Build request
    let mut query_parts = Vec::new();
    if let Some(val) = site.as_ref() {
        query_parts.push(format!("site={}", val));
    }
    if let Some(val) = type_rs.as_ref() {
        query_parts.push(format!("type={}", val));
    }
    if let Some(val) = cursor.as_ref() {
        query_parts.push(format!("cursor={}", val));
    }
    if let Some(val) = limit.as_ref() {
        query_parts.push(format!("limit={}", val));
    }

    let url_with_query = if query_parts.is_empty() {
        endpoint_url
    } else {
        format!("{}?{}", endpoint_url, query_parts.join("&"))
    };

    let builder = client.get(&url_with_query)
        .map_err(|e| ApiError::RequestBuildFailed(e.to_string()))?;

    Ok(builder)
}

