/// GET /accounts/{account_id}/magic/cloud/providers
/// List Cloud Integrations
///
/// Returns `ClientRequestBuilder` for customization.
/// Use `providers_list_execute()` to send, or `providers_list` for simplest API.

pub fn providers_list_builder(
    client: &SimpleHttpClient,
    account_id: &String,
    status: &Option<Option<String>>,
    order_by: &Option<Option<String>>,
    desc: &Option<Option<String>>,
    cloudflare: &Option<Option<String>>,
) -> Result<ClientRequestBuilder<SystemDnsResolver>, ApiError> {

    // Build URL
    let endpoint_url = format!(
        "https://api.cloudflare.com/client/v4/accounts/{}/magic/cloud/providers",
        account_id,
    );

    // Build request
    let mut query_parts = Vec::new();
    if let Some(val) = status.as_ref() {
        query_parts.push(format!("status={}", val));
    }
    if let Some(val) = order_by.as_ref() {
        query_parts.push(format!("order_by={}", val));
    }
    if let Some(val) = desc.as_ref() {
        query_parts.push(format!("desc={}", val));
    }
    if let Some(val) = cloudflare.as_ref() {
        query_parts.push(format!("cloudflare={}", val));
    }

    let url_with_query = if query_parts.is_empty() {
        endpoint_url
    } else {
        format!("{}?{}", endpoint_url, query_parts.join("&"))
    };

    let builder = client.get(&url_with_query)
        .map_err(|e| ApiError::RequestBuildFailed(e.to_string()))?;

    Ok(builder)
}

