pub fn list_namespaces_builder(
    client: &SimpleHttpClient,
    account_id: &String,
    bucket_name: &String,
    page_token: &Option<Option<String>>,
    page_size: &Option<Option<String>>,
    parent: &Option<Option<String>>,
    return_uuids: &Option<Option<String>>,
    return_details: &Option<Option<String>>,
) -> Result<ClientRequestBuilder<SystemDnsResolver>, ApiError> {

    // Build URL
    let endpoint_url = format!(
        "https://api.cloudflare.com/client/v4/accounts/{}/r2-catalog/{}/namespaces",
        account_id,
        bucket_name,
    );

    // Build request
    let mut query_parts = Vec::new();
    if let Some(val) = page_token.as_ref() {
        query_parts.push(format!("page_token={}", val));
    }
    if let Some(val) = page_size.as_ref() {
        query_parts.push(format!("page_size={}", val));
    }
    if let Some(val) = parent.as_ref() {
        query_parts.push(format!("parent={}", val));
    }
    if let Some(val) = return_uuids.as_ref() {
        query_parts.push(format!("return_uuids={}", val));
    }
    if let Some(val) = return_details.as_ref() {
        query_parts.push(format!("return_details={}", val));
    }

    let url_with_query = if query_parts.is_empty() {
        endpoint_url
    } else {
        format!("{}?{}", endpoint_url, query_parts.join("&"))
    };

    let builder = client.get(&url_with_query)
        .map_err(|e| ApiError::RequestBuildFailed(e.to_string()))?;

    Ok(builder)
}

